-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(materialized='table') }}

with
quarantined as (
    select
        vantora_gp_id,
        gp_name,
        gp_lei,
        shared_external_id,
        domicile,
        relationship_start_date,
        violation_00,
        violation_01,
        violation_02
    from {{ ref("investment__vantora_gp_extract__checked") }}
),
violations as (
    select
        'vantora_gp_id_not_null' as rule_name,
        vantora_gp_id,
        gp_name,
        gp_lei,
        shared_external_id,
        domicile,
        relationship_start_date
    from quarantined
    where violation_00

    union all

    select
        'vantora_gp_id_unique' as rule_name,
        vantora_gp_id,
        gp_name,
        gp_lei,
        shared_external_id,
        domicile,
        relationship_start_date
    from quarantined
    where violation_01

    union all

    select
        'gp_name_not_null' as rule_name,
        vantora_gp_id,
        gp_name,
        gp_lei,
        shared_external_id,
        domicile,
        relationship_start_date
    from quarantined
    where violation_02
)

select
    rule_name,
    vantora_gp_id,
    gp_name,
    gp_lei,
    shared_external_id,
    domicile,
    relationship_start_date
from violations
